',children:'/// How long the bank\'s review of a held payment takes.\nconst HOLD: Duration = Duration::from_secs(30);\n\n#[subscriber(GooglePubSub::new("payments-workers").create_with_topic("payments"))]\nasync fn charge(payment: &Payment, ctx: &mut Context<\'_>) -> HandlerOutcome {\n    let attempt = ctx\n        .headers()\n        .get_str(DELIVERY_ATTEMPT_HEADER)\n        .unwrap_or("1");\n    match ask_the_bank(payment) {\n        Answer::Charged => HandlerOutcome::ack(),\n        Answer::Held => {\n            tracing::info!(\n                payment.id,\n                attempt,\n                "payment held by the bank, asked again later"\n            );\n            HandlerOutcome::retry_after(HOLD)\n        }\n        Answer::Unreachable => {\n            tracing::warn!(payment.id, attempt, "bank unreachable, payment retried");\n            HandlerOutcome::retry()\n        }\n        Answer::Declined => {\n            tracing::warn!(payment.id, "card declined, payment dropped");\n            HandlerOutcome::drop()\n        }\n    }\n}\n'})})}),(0,a.jsx)(o.A,{value:"manual",label:"Manual",children:(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-rust",metastring:'title="src/main.rs"',children:'/// How long the bank\'s review of a held payment takes.\nconst HOLD: Duration = Duration::from_secs(30);\n\nstruct Charge;\n\nimpl Handle<Payment> for Charge {\n    fn handle(\n        &self,\n        payment: &Payment,\n        _outs: &(),\n        ctx: &mut Context<\'_>,\n    ) -> impl Future<Output = Result<(), HandlerOutcome>> {\n        let attempt = ctx\n            .headers()\n            .get_str(DELIVERY_ATTEMPT_HEADER)\n            .unwrap_or("1");\n        let settled = match ask_the_bank(payment) {\n            Answer::Charged => Ok(()),\n            Answer::Held => {\n                tracing::info!(\n                    payment.id,\n                    attempt,\n                    "payment held by the bank, asked again later"\n                );\n                Err(HandlerOutcome::retry_after(HOLD))\n            }\n            Answer::Unreachable => {\n                tracing::warn!(payment.id, attempt, "bank unreachable, payment retried");\n                Err(HandlerOutcome::retry())\n            }\n            Answer::Declined => {\n                tracing::warn!(payment.id, "card declined, payment dropped");\n                Err(HandlerOutcome::drop())\n            }\n        };\n        ready(settled)\n    }\n}\n'})})})]}),"\n",(0,a.jsx)(t.p,{children:"On Pub/Sub the outcomes become these calls:"}),"\n",(0,a.jsxs)(t.table,{children:[(0,a.jsx)(t.thead,{children:(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.th,{children:"Outcome"}),(0,a.jsx)(t.th,{children:"What Pub/Sub does"})]})}),(0,a.jsxs)(t.tbody,{children:[(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.code,{children:"ack"})}),(0,a.jsx)(t.td,{children:"acknowledges; the message is not delivered again"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.code,{children:"retry"})}),(0,a.jsx)(t.td,{children:"nacks; the subscription delivers the message again"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.code,{children:"retry_after(delay)"})}),(0,a.jsx)(t.td,{children:"the service holds the message under its lease for the delay, then nacks it"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.code,{children:"drop"})}),(0,a.jsx)(t.td,{children:"acknowledges; on the last delivery the cap allows, nacks, so the message goes to the dead-letter topic"})]})]})]}),"\n",(0,a.jsxs)(t.p,{children:["A subscription with no retry policy delivers a nacked message again at once.\nA subscription with an exponential backoff policy, set by operations, waits first, and then ",(0,a.jsx)(t.code,{children:"retry"})," waits too."]}),"\n",(0,a.jsxs)(t.p,{children:["Pub/Sub has no delayed nack, so ",(0,a.jsx)(t.a,{href:"/ruststream-gcp-pubsub/next/components/settlement/retry-after",children:(0,a.jsx)(t.code,{children:"retry_after"})})," keeps the message in the service.\nThe client goes on extending its lease for the delay, and nacks it when the delay is over.\nThe delay must fit inside the subscription's ",(0,a.jsx)(t.a,{href:"/ruststream-gcp-pubsub/next/components/subscriptions/max-lease",children:(0,a.jsx)(t.code,{children:"max_lease"})}),", an hour by default; a longer one comes back at once.\nA service that stops during the delay stops extending the lease, and the message comes back when the lease runs out.\n",(0,a.jsx)(t.a,{href:"/ruststream-gcp-pubsub/next/guides/flow-control",children:"Flow control and leases"})," covers the lease."]}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.a,{href:"/ruststream-gcp-pubsub/next/components/settlement/attempts",children:(0,a.jsx)(t.code,{children:"DELIVERY_ATTEMPT_HEADER"})})," is the delivery's attempt number, the first delivery being 1.\nPub/Sub counts attempts only on a subscription with a dead-letter policy, and its count is an estimate that may miss a delivery."]}),"\n",(0,a.jsx)(t.h2,{id:"the-cap-and-the-dead-letter-topic",children:"The cap and the dead-letter topic"}),"\n",(0,a.jsxs)(i.A,{groupId:"api",children:[(0,a.jsx)(o.A,{value:"macros",label:"Macros",children:(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-rust",metastring:'title="src/main.rs"',children:'#[ruststream::app]\nfn app() -> impl App {\n    RustStream::new(AppInfo::new("payments", "0.1.0")).with_broker(\n        PubSubBroker::new("my-project").emulator("localhost:8085"),\n        |b| {\n            // Five deliveries of one payment, the first included; then `payments-dead`.\n            b.include(charge)\n                .max_attempts(nonzero!(5u32))\n                .dead_letter("payments-dead");\n            b.include(review);\n        },\n    )\n}\n'})})}),(0,a.jsx)(o.A,{value:"manual",label:"Manual",children:(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-rust",metastring:'title="src/main.rs"',children:'fn app() -> impl App {\n    RustStream::new(AppInfo::new("payments", "0.1.0")).with_broker(\n        PubSubBroker::new("my-project").emulator("localhost:8085"),\n        |b| {\n            // Five deliveries of one payment, the first included; then `payments-dead`.\n            b.include(\n                subscriber(\n                    GooglePubSub::new("payments-workers").create_with_topic("payments"),\n                    Charge,\n                )\n                .build(),\n            )\n            .max_attempts(nonzero!(5u32))\n            .dead_letter("payments-dead");\n            b.include(\n                subscriber(\n                    GooglePubSub::new("payments-dead-review").create_with_topic("payments-dead"),\n                    Review,\n                )\n                .build(),\n            );\n        },\n    )\n}\n\nfn main() -> ExitCode {\n    run_main(app)\n}\n'})})})]}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.a,{href:"https://docs.rs/ruststream/0.7/ruststream/runtime/struct.Mounting.html#method.max_attempts",children:(0,a.jsx)(t.code,{children:"max_attempts"})})," and ",(0,a.jsx)(t.a,{href:"https://docs.rs/ruststream/0.7/ruststream/runtime/struct.Mounting.html#method.dead_letter",children:(0,a.jsx)(t.code,{children:"dead_letter"})})," become the subscription's own dead-letter policy, written at startup.\nAfter the fifth delivery Pub/Sub stops delivering the payment and publishes it to ",(0,a.jsx)(t.code,{children:"payments-dead"}),", payload and attributes as they arrived.\nThe service publishes nothing itself, so a crash cannot lose the move.\nPub/Sub accepts a cap from 5 to 100; anything else, or one half of the pair alone, fails the startup.\nA dropped payment is acknowledged and goes nowhere; the dead-letter topic holds only the payments that ran out of deliveries."]}),"\n",(0,a.jsxs)(t.p,{children:["The subscription ",(0,a.jsx)(t.code,{children:"payments-workers"})," is created with the policy, and the topic ",(0,a.jsx)(t.code,{children:"payments-dead"})," with it.\nA subscription operations created gets the policy written onto it at startup instead.\nIn production the Pub/Sub service account of the project needs permission to publish to the dead-letter topic and to subscribe to the source subscription; ",(0,a.jsx)(t.a,{href:"/ruststream-gcp-pubsub/next/guides/production",children:"Running in production"})," lists the roles."]}),"\n",(0,a.jsx)(t.h2,{id:"reading-the-dead-letter-topic",children:"Reading the dead-letter topic"}),"\n",(0,a.jsxs)(i.A,{groupId:"api",children:[(0,a.jsx)(o.A,{value:"macros",label:"Macros",children:(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-rust",metastring:'title="src/main.rs"',children:'/// Reads the dead-letter topic through a subscription of its own.\n#[subscriber(GooglePubSub::new("payments-dead-review").create_with_topic("payments-dead"))]\nasync fn review(payment: &Payment) -> HandlerOutcome {\n    tracing::error!(\n        payment.id,\n        "payment ran out of attempts, a person looks at it"\n    );\n    HandlerOutcome::ack()\n}\n'})})}),(0,a.jsx)(o.A,{value:"manual",label:"Manual",children:(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-rust",metastring:'title="src/main.rs"',children:'/// Reads the dead-letter topic through a subscription of its own.\nstruct Review;\n\nimpl Handle<Payment> for Review {\n    fn handle(\n        &self,\n        payment: &Payment,\n        _outs: &(),\n        _ctx: &mut Context<\'_>,\n    ) -> impl Future<Output = Result<(), HandlerOutcome>> {\n        tracing::error!(\n            payment.id,\n            "payment ran out of attempts, a person looks at it"\n        );\n        ready(Ok(()))\n    }\n}\n'})})})]}),"\n",(0,a.jsxs)(t.p,{children:["The dead-letter topic is an ordinary topic, and ",(0,a.jsx)(t.code,{children:"review"})," reads it through a subscription of its own.\nA message published to a topic with no subscription is lost, so the subscription exists before the first payment runs